--
-- Table structure for table `applications`
--

DROP TABLE IF EXISTS `applications`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `applications` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `candidate_id` bigint NOT NULL,
  `session_id` bigint NOT NULL,
  `major_id` bigint NOT NULL,
  `priority_order` int DEFAULT '1',
  `score` decimal(4,2) DEFAULT NULL,
  `status` enum('ADMITTED','APPROVED','DRAFT','ENROLLED','NEED_SUPPLEMENT','NOT_ADMITTED','REJECTED','SUBMITTED') COLLATE utf8mb4_unicode_ci NOT NULL,
  `submitted_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `note` text COLLATE utf8mb4_unicode_ci,
  `biology_score` decimal(4,2) DEFAULT NULL,
  `chemistry_score` decimal(4,2) DEFAULT NULL,
  `civic_score` decimal(4,2) DEFAULT NULL,
  `english_score` decimal(4,2) DEFAULT NULL,
  `geography_score` decimal(4,2) DEFAULT NULL,
  `history_score` decimal(4,2) DEFAULT NULL,
  `literature_score` decimal(4,2) DEFAULT NULL,
  `math_score` decimal(4,2) DEFAULT NULL,
  `physics_score` decimal(4,2) DEFAULT NULL,
  `subject_group` enum('NATURAL','SOCIAL') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admission_combination` enum('A00','A01','B00','C00','C19','C20','D01','D14') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_app_major` (`major_id`),
  KEY `idx_application_status` (`status`),
  KEY `idx_application_session` (`session_id`),
  KEY `idx_application_candidate` (`candidate_id`),
  CONSTRAINT `fk_app_candidate` FOREIGN KEY (`candidate_id`) REFERENCES `candidates` (`id`) ON DELETE CASCADE,
  CONSTRAINT `fk_app_major` FOREIGN KEY (`major_id`) REFERENCES `majors` (`id`),
  CONSTRAINT `fk_app_session` FOREIGN KEY (`session_id`) REFERENCES `admission_sessions` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1078 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `applications`
--

